const createWeb = require('express');
const gateway = createWeb();
const diagnostic = '/ops/' + 'alive';
gateway.get(diagnostic, (_req, res) => res.send('alive'));
gateway.listen(4637);

const createWeb = require('express');
const gateway = createWeb();
let diagnostic = '/ops/' + 'alive';
diagnostic = process.env.PROBE_ROUTE;
gateway.get(diagnostic, (_req, res) => res.send('alive'));
gateway.listen(4637);

const createWeb = require('express');
const gateway = createWeb();
const diagnostic = '/ops/' + 'alive';
function register(diagnostic) {
  gateway.get(diagnostic, (_req, res) => res.send('alive'));
}
register(process.env.PROBE_ROUTE);
gateway.listen(4637);

